#include <iostream>
#include <algorithm>
using namespace std;

using li = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    li x0, x1, a, b;
    cin >> x0 >> x1 >> a >> b;

    li direction = 1;

    if (x1 < x0) {
        swap(x0, x1);
        swap(a, b);
        a = -a;
        b = -b;
        direction = -1;
    }

    li dis = x1 - x0;

    auto printFirst = [&](li move) {
        cout << "FIRST\n" << direction * move << '\n';
    };

    if (a <= dis && dis <= b) {
        printFirst(dis);
        return 0;
    }

    if (a <= 0) {
        cout << "DRAW\n";
        return 0;
    }

    dis %= (a + b);

    if (dis == 0) {
        cout << "SECOND\n";
    } else if (dis < a) {
        cout << "DRAW\n";
    } else if (dis <= b) {
        printFirst(dis);
    } else {
        cout << "DRAW\n";
    }

    return 0;
}

